  "definitions": [
    {
      "term": {
        "text": "string literal",
        "refs": ["Q0000"]
      },
      "definition_text": {
        "text": "a string value written directly in the source code, e.g., \"hello world\", which the Java compiler treats as an instance of the String class",
        "refs": ["Q0000"]
      },
      "context": null
    },
    {
      "term": {
        "text": "reference type",
        "refs": ["Q0001"]
      },
      "definition_text": {
        "text": "a type whose variables hold references to objects rather than the actual primitive data values; in Java, classes such as String are reference types",
        "refs": ["Q0001"]
      },
      "context": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "The String class is defined in the java.lang package, which is automatically imported by the Java compiler",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "String variables can be instantiated without the new operator by assigning a string literal",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Using \"new String\" is redundant because the same result is achieved with a string literal",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The plus (+) operator concatenates two strings",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The method endsWith returns a boolean indicating whether a string ends with the specified suffix",
        "refs": ["Q0003", "Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The method startsWith returns a boolean indicating whether a string starts with the specified prefix",
        "refs": ["Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The method length returns the number of characters in the string",
        "refs": ["Q0004", "Q0005"]
      },
      "fact_type": null
    }
  ],
  "examples": [
    {
      "example_type": null,
      "example_text": {
        "text": "String message = \"hello world\"; // using a string literal instead of new String",
        "refs": ["Q0001"]
      },
      "exemplifies": {
        "text": "initializing a String variable without the new operator",
        "refs": ["Q0001"]
      }
    },
    {
      "example_type": null,
      "example_text": {
        "text": "String combined = message + \"!!\"; // concatenation with + operator",
        "refs": ["Q0002"]
      },
      "exemplifies": {
        "text": "concatenating strings using the plus operator",
        "refs": ["Q0002"]
      }
    },
    {
      "example_type": null,
      "example_text": {
        "text": "boolean ends = message.endsWith(\"!!\"); // returns true",
        "refs": ["Q0003", "Q0004"]
      },
      "exemplifies": {
        "text": "checking if a string ends with a given suffix",
        "refs": ["Q0003", "Q0004"]
      }
    },
    {
      "example_type": null,
      "example_text": {
        "text": "int len = message.length(); // returns 13 for \"hello world!!\"",
