      },
      "exemplifies": {
        "text": "retrieving the length of a string",
        "refs": ["Q0005"]
      }
    }
  ],
  "explanations": [
    {
      "topic": {
        "text": "Why \"new String\" is redundant",
        "refs": ["Q0001"]
      },
      "explanation_text": {
        "text": "String literals are a shorthand that the compiler translates into a String object, so explicitly calling the String constructor adds no benefit and can be omitted",
        "refs": ["Q0001"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "String methods accessed via dot operator",
        "refs": ["Q0003"]
      },
      "explanation_text": {
        "text": "Because String is a class, its instance methods (e.g., endsWith, startsWith, length) are invoked using the dot (.) syntax on a String variable",
        "refs": ["Q0003"]
      },
      "explanation_type": null
    }
  ],
